function getReachable(unit){let seen=new Map([[key(unit.q,unit.r),0]]),front=[{q:unit.q,r:unit.r}];while(front.length){let cur=front.shift(),cost=seen.get(key(cur.q,cur.r));for(let [q,r] of neighbors(cur.q,cur.r)){if(q<0||r<0||q>=cols||r>=rows)continue;let t=cell(q,r);if(t.type==='river')continue;let step=t.type==='jungle'?2:1,nd=cost+step,k=key(q,r);if(nd>2||seen.has(k)||units.some(u=>u.hp>0&&u.q===q&&u.r===r))continue;seen.set(k,nd);front.push({q,r})}}return [...seen.keys()].filter(k=>k!==key(unit.q,unit.r)).map(k=>{let[q,r]=k.split(',').map(Number);return{q,r}})}
function onTile(q,r){if(!started||ended)return;let occupant=units.find(u=>u.hp>0&&u.q===q&&u.r===r);if(mode==='fire'){if(occupant?.side==='enemy'){fireAt(occupant);return}say('No hostile unit at that position.');return}if(mode==='move'&&selected){let reachable=getReachable(selected);if(reachable.some(p=>p.q===q&&p.r===r)){selected.q=q;selected.r=r;selected.moved=true;mode='';addLog(`${selected.name} moved to grid ${String.fromCharCode(65+q)}${r+1}.`);if(sites.some(s=>s.q===q&&s.r===r))say(`${selected.name} secured the ${sites.find(s=>s.q===q&&s.r===r).name}.`);render();return}if(occupant?.side==='enemy')say('Movement blocked by a hostile contact.');else say('That position is outside this squad’s movement range.');return}if(occupant?.side==='friendly'){selected=occupant;mode='';render();return}if(occupant?.side==='enemy'){selected=occupant;render();return}if(selected?.side==='friendly')selected=null;render()}
function fireAt(target){if(!selected||selected.side!=='friendly'){say('Select a friendly squad before firing.');return}if(selected.fired){say(`${selected.name} has already fired today.`);return}if(distance(selected,target)>4){say('Target is beyond effective range. Move closer.');return}let hit=Math.random()<.78;selected.fired=true;mode='';if(hit){target.hp--;addLog(`${selected.name} engaged ${target.name} — hit.`);if(target.hp<=0){addLog(`${target.name} is no longer in contact.`);units.splice(units.indexOf(target),1)}}else addLog(`${selected.name} fired on ${target.name} — missed.`);render();checkResult()}
function rally(unit=selected){if(!unit||unit.side!=='friendly'){say('Select a friendly squad to rally.');return}if(unit.acted){say(`${unit.name} has already acted today.`);return}let wounded=units.filter(u=>u.side==='friendly'&&u.hp<u.max&&distance(u,unit)<=1);if(unit.role.includes('MEDIC')){if(!wounded.length){say('No wounded squad in reach of Doc Mercer.');return}let healed=wounded[0];healed.hp++;unit.acted=true;addLog(`Doc Mercer treated ${healed.name}.`);say(`${healed.name} recovered one strength.`)}else{unit.acted=true;addLog(`${unit.name} rallied — ready to hold position.`);say(`${unit.name} steadies the line. Hostile fire will be less effective.`)}render()}
function command(action){if(action==='end'){endTurn();return}if(!started||ended)return;if(action==='move'){if(!selected||selected.side!=='friendly'){say('Select one of your squads first.');return}if(selected.moved){say(`${selected.name} has already moved today.`);return}mode=mode==='move'?'':'move';say(mode?'Choose a highlighted tile to move.':'Move order cancelled.');render()}else if(action==='fire'){if(!selected||selected.side!=='friendly'){say('Select one of your squads first.');return}if(selected.fired){say(`${selected.name} has already fired today.`);return}mode=mode==='fire'?'':'fire';say(mode?'Choose a marked hostile contact to fire.':'Fire order cancelled.');render()}else if(action==='rally')rally()}
function endTurn(){if(!started||ended)return;mode='';selected=null;enemyPhase();if(checkResult())return;turn++;if(turn>6){ended=true;render();showResult(false);return}for(let u of units.filter(x=>x.side==='friendly')){u.moved=false;u.fired=false;u.acted=false}addLog(`Day ${turn} — Echo platoon, your orders.`);render();say(`Day ${turn}. The platoon is ready.`)}
function enemyPhase(){document.getElementById('phaseLabel').textContent='● CONTACTS MOVING';for(let e of units.filter(u=>u.side==='enemy')){if(!units.includes(e))continue;let friendlies=units.filter(u=>u.side==='friendly');if(!friendlies.length)break;let near=friendlies.sort((a,b)=>distance(e,a)-distance(e,b))[0];if(distance(e,near)<=3){if(Math.random()<.58){near.hp--;addLog(`${e.name} opened fire — ${near.name} hit.`);if(near.hp<=0){units.splice(units.indexOf(near),1);if(selected===near)selected=null;addLog(`${near.name} has been lost.`)}}else addLog(`${e.name} fired and missed.`)}else{let opts=neighbors(e.q,e.r).filter(([q,r])=>q>=0&&r>=0&&q<cols&&r<rows&&cell(q,r).type!=='river'&&!units.some(u=>u.hp>0&&u.q===q&&u.r===r)).sort((a,b)=>distance({q:a[0],r:a[1]},near)-distance({q:b[0],r:b[1]},near));if(opts.length){e.q=opts[0][0];e.r=opts[0][1]}}}document.getElementById('phaseLabel').textContent='● YOUR ORDERS';render()}
function checkResult(){let occupied=sites.filter(s=>units.some(u=>u.side==='friendly'&&u.q===s.q&&u.r===s.r)).length;if(occupied===2&&turn>=6){ended=true;showResult(true);return true}if(!units.some(u=>u.side==='friendly')){ended=true;showResult(false,true);return true}return false}
function showResult(win,lost=false){let ov=document.getElementById('briefing');ov.style.display='grid';ov.innerHTML=`<div class="modal"><div class="modal-stamp">After-action report · ${win?'Mission accomplished':'Operation concluded'}</div><div class="result-mark">${win?'✦':'◌'}</div><h1>${win?'Signal restored':'Lost in the highlands'}</h1><div class="intro">${win?'Echo platoon secured both relay positions and held the ridge until extraction. The valley is back on the map.':'The platoon can no longer continue the mission. The ridge remains contested.'}</div><div class="brief-grid"><div class="brief-box"><b>Days elapsed</b><span>${Math.min(turn,6)} / 6</span></div><div class="brief-box"><b>Squads remaining</b><span>${units.filter(u=>u.side==='friendly').length} / 4</span></div></div><button class="command-btn primary" id="restartBtn">Run the operation again &nbsp; ↻</button></div>`;document.getElementById('restartBtn').onclick=()=>location.reload();render()}
function addLog(text){logs.unshift(text);logs=logs.slice(0,4);renderLog()}
function renderLog(){document.getElementById('radioLog').innerHTML=logs.map((t,i)=>`<div class="log-line">${i===0?'› ':''}${escapeHTML(t)}</div>`).join('')}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function say(text){let t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function render(){draw();renderUnits();renderSelection();updateControls();let count=sites.filter(s=>units.some(u=>u.side==='friendly'&&u.q===s.q&&u.r===s.r)).length;document.getElementById('objectiveCount').textContent=`${count} / 2`;document.getElementById('objectiveProgress').style.width=`${count*50}%`;document.getElementById('turnLabel').textContent=`${String(Math.min(turn,6)).padStart(2,'0')} / 06`;document.getElementById('squadCount').textContent=`${units.filter(u=>u.side==='friendly').length} active`;document.getElementById('enemyCount').textContent=`${units.filter(u=>u.side==='enemy').length} contacts`;document.getElementById('mapHint').textContent=mode==='move'?'CHOOSE A HIGHLIGHTED TILE':mode==='fire'?'SELECT A MARKED HOSTILE CONTACT':selected?.side==='friendly'?`${selected.name.toUpperCase()} · ${selected.moved?'MOVED':'MOVE READY'} / ${selected.fired?'FIRED':'FIRE READY'}`:'SELECT A SQUAD TO ISSUE ORDERS';document.getElementById('phaseLabel').textContent=mode?'● '+(mode==='move'?'MOVE ORDER':'FIRE ORDER'):'● YOUR ORDERS';}
function renderUnits(){let friend=units.filter(u=>u.side==='friendly'),enemy=units.filter(u=>u.side==='enemy');document.getElementById('friendlyList').innerHTML=friend.map(u=>unitCard(u)).join('')||'<div class="unit-meta" style="padding:8px">No platoon units remaining.</div>';document.getElementById('enemyList').innerHTML=enemy.map(u=>unitCard(u)).join('')||'<div class="unit-meta" style="padding:8px">No enemy contacts on the ridge.</div>';document.querySelectorAll('.unit-card').forEach(b=>b.onclick=()=>{selected=units.find(u=>u.id===b.dataset.id);mode='';render()})}
function unitCard(u){let selectedCls=selected?.id===u.id?'selected':'',spent=u.side==='friendly'&&(u.moved&&u.fired||u.acted);return `<button class="unit-card ${selectedCls} ${spent?'spent':''}" data-id="${u.id}"><span class="unit-token ${u.side==='enemy'?'enemy':''}">${u.icon}</span><span class="unit-info"><span class="unit-name">${escapeHTML(u.name)}</span><span class="unit-meta">${u.role} · ${String.fromCharCode(65+u.q)}${u.r+1}</span><span class="health">${Array.from({length:u.max},(_,i)=>`<i class="${i>=u.hp?'low':''}"></i>`).join('')}</span></span><span class="unit-state ${spent?'used':''}">${u.side==='enemy'?'CONTACT':spent?'DONE':u.moved?'MOVED':'READY'}</span></button>`}
function renderSelection(){let box=document.getElementById('selectedCard');if(!selected){box.innerHTML='<div class="selected-title">No squad selected</div><div class="selected-meta">Choose a friendly unit on the map or in the roster.</div>';return}let friendly=selected.side==='friendly';box.innerHTML=`<div class="selected-title">${escapeHTML(selected.name)} ${friendly?'':'· HOSTILE'}</div><div class="selected-meta">${selected.role} · GRID ${String.fromCharCode(65+selected.q)}${selected.r+1}<br>${friendly?`Strength ${selected.hp}/${selected.max} · Move ${selected.moved?'spent':'ready'} · Fire ${selected.fired?'spent':'ready'}`:`Strength ${selected.hp}/${selected.max} · Effective range 4`}</div>`}
function updateControls(){document.querySelectorAll('[data-action]').forEach(b=>{let a=b.dataset.action,disabled=!started||ended;if(a!=='end'&&(!selected||selected.side!=='friendly'))disabled=true;if(a==='move'&&selected?.moved)disabled=true;if(a==='fire'&&selected?.fired)disabled=true;if(a==='rally'&&selected?.acted)disabled=true;b.disabled=disabled;b.classList.toggle('active',mode===a)})}
// Wire command surfaces, briefing, keyboard, and touch-friendly map behavior.
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>command(b.dataset.action)));
document.getElementById('startBtn').onclick=()=>{started=true;document.getElementById('briefing').style.display='none';addLog('Echo platoon deployed. Secure both relay sites.');render();say('Orders are live. Move toward the signal sites.')};
document.getElementById('helpBtn').onclick=()=>{if(!started){document.getElementById('briefing').style.display='grid';return}say('Capture both gold relay diamonds. Select a squad, then Move, Fire, or Rally. End Day to advance hostile patrols.')};
document.addEventListener('keydown',e=>{if(!started||ended)return;if(e.key.toLowerCase()==='m')command('move');if(e.key.toLowerCase()==='f')command('fire');if(e.key==='Escape'){mode='';render()}if(e.key==='Enter')endTurn()});
logs=['Echo platoon standing by.'];draw();renderLog();render();
})();
</script>
</body>
</html>

